contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call sequence: optionally send funds into C via fallback by sending ether to C (using depositAmt),
    // then attempt withdrawAll by caller 'msg.sender' of this function. On the original contract P onlyOwner
    // prevents non-owners from reducing C's balance; the mutant M allows anyone to withdraw.
    function runTest(uint depositAmt, uint withdrawAmt) public payable {
        // Preconditions: this test caller must supply the depositAmt as msg.value to this function
        require(msg.value == depositAmt, "must forward depositAmt");
        require(depositAmt > 0, "need positive deposit");

        // Send the depositAmt from this contract (msg.sender of runTest) into C by calling C's fallback
        // Achieve that by making a plain call with value to address(c).
        (bool sent,) = address(c).call{value: depositAmt}(new bytes(0));
        require(sent, "deposit to C failed");

        // Record C balance before withdraw attempt
        uint before = address(c).balance;

        // Attempt to withdraw withdrawAmt by calling withdrawAll which in mutant allows anyone to withdraw
        // We call withdrawAll (state-changing) as its own top-level statement per rules.
        c.withdrawAll();

        // Observe C balance after
        uint after = address(c).balance;

        // Rule: if the caller is NOT the owner, C's balance must NOT decrease (only owner can withdraw funds).
        // We express this by querying c.owner() and comparing to msg.sender.
        // If msg.sender != owner then after >= before.
        address owner = c.owner();
        assert(owner == msg.sender || after >= before);
    }

    // Allow this contract to receive refunds if any
    receive() external payable {}
}

