pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address depositor = address(0xBEEF);

    function setUp() public { c = new C(); }

    // fuzzed params: amount deposited (must be >0 to observe difference)
    function testFuzz_property(uint256 depositAmount) public {
        // keep depositAmount in a wide admissible domain but non-zero
        vm.assume(depositAmount > 0);
        // give depositor enough ETH
        vm.deal(depositor, depositAmount);
        // depositor sends ETH to contract (triggers fallback and increases depositsCount)
        vm.prank(depositor);
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent);

        // record balance before withdrawAll
        uint256 before = address(c).balance;
        // owner (deployer of c) calls withdrawAll
        // set msg.sender to the owner (already the test runner is deployer of c)
        // call withdrawAll
        c.withdrawAll();
        // After withdrawAll the contract balance should be zero (entire balance transferred to owner)
        // This is the universal property the reference satisfies; the mutant that calls withdraw(0) will fail for some depositAmount > 0
        assertTrue(address(c).balance == 0);
    }
}

