import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the deposit amount (must be >0) and an external actor (unused except as possible payer)
    function testFuzz_property(uint256 depositAmount, address payer) public {
        // keep depositAmount in a wide admissible domain but nonzero and not absurdly large
        depositAmount = bound(depositAmount, 1, 1 ether);
        // ensure payer is a usable address with funds
        if (payer == address(0)) payer = address(1);
        vm.deal(payer, depositAmount);

        // payer sends ETH to the contract (fallback increments depositsCount but we only need balance)
        vm.prank(payer);
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent);

        // record balance before withdrawAll
        uint256 before = address(c).balance;
        // sanity: should equal depositAmount (owner has not moved funds yet)
        // The property we assert universally is about withdrawAll succeeding and reducing balance to zero
        // when called by the owner. Owner is deployer (test contract's msg.sender at deploy time), which is address(this) in setUp.

        // call withdrawAll as owner
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = address(c).balance;

        // GENERAL rule: For any admissible nonzero depositAmount, the reference's withdrawAll succeeds (ok==true)
        // and transfers out the contract balance, so after < before (indeed after==0). The mutant withdrawAll calling withdraw(0)
        // will leave the balance unchanged (after==before) for some inputs. We assert that the call succeeded and the balance decreased.
        assertTrue(ok && after < before);
    }
}

