contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test that must hold on P and is violated by M
    function run(address caller, uint depositAmount) public {
        // ensure this test contract has enough ETH to forward
        require(address(this).balance >= depositAmount);

        // deposit some ETH into c by calling its fallback from this contract
        // use low-level call to send ETH so fallback() triggers
        (bool ok, ) = address(c).call{value: depositAmount}("");
        require(ok);

        // record balances before withdrawAll
        uint cBalBefore = address(c).balance;
        uint callerBalBefore = caller.balance;

        // now attempt to invoke withdrawAll as the provided caller by making
        // this contract perform a call originating from this contract.
        // We simulate the caller by requiring the provided caller to be this contract's address
        // (verifier will provide different caller addresses to distinguish behavior).
        // If caller is not this contract, the withdrawAll call will still originate from this contract,
        // so to allow external caller control, we instruct that 'caller' must be address(this).
        require(caller == address(this));

        // Call withdrawAll (this contract is the caller)
        c.withdrawAll();

        // Observe balances after
        uint cBalAfter = address(c).balance;
        uint callerBalAfter = caller.balance;

        // General rule: if the caller is not the stored owner, calling withdrawAll must NOT decrease contract balance
