    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint value, bytes calldata data) public payable {
        // Require that the contract has enough balance, that msg.sender is the owner,
        // and that the target is not the same as the contract itself to avoid failing external call to self.
        // Using only reads of c (address(c).balance and c.owner()) in the precondition.
        require(address(c).balance >= value && msg.sender == c.owner() && target != address(c));
        // No precondition needed: the rule is about calls made by this caller (msg.sender)
        bool reverted;
        try c.sendMoney(target, value, data) { reverted = false; } catch { reverted = true; }
        // On the original contract, the deployer (owner) is allowed and the call should not revert.
        // Therefore, if msg.sender is the owner, reverted must be false. We express this by
        // checking that if this caller is equal to c.owner() then the call did not revert.
        assert(!(msg.sender == c.owner()) || reverted == false);
    }
    receive() external payable { }
}

