pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to send and arbitrary bytes data
    function testFuzz_property(uint256 value, bytes memory data) public {
        // keep value within contract balanceable bounds
        uint256 sendAmt = bound(value, 0, 1 ether);

        // fund the contract so owner can send funds out
        vm.deal(address(this), 2 ether);
        // deposit some ETH into c by calling fallback via direct call (fallback increments depositsCount)
        (bool sent,) = address(c).call{value: 1 ether}("");
        require(sent);

        // The owner is the deployer (this contract). We will call sendMoney as the owner.
        // send target is an EOA (address(0x1234)) which will accept calls; fuzzing focuses on value and data.
        address target = address(0x1234);

        // call sendMoney as owner with fuzzed amount and data
        bool ok;
        try c.sendMoney{value: 0}(target, sendAmt, data) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): In the reference contract the owner is allowed to call sendMoney,
        // so any call performed as the owner should NOT revert (ok == true) for all admissible inputs.
        // The mutant flips the owner check and will cause some of these owner calls to revert (ok == false).
        assertTrue(ok);
    }
}
